const invariantNames = [
  "Maceió", "Macapá", "Brasília", "Vitória", "Goiânia", "São Luís", "Cuiabá",
  "Belém", "João Pessoa", "Florianópolis", "São Paulo", "São Carlos", "Amapá",
  "Ceará", "Espírito Santo", "Goiás", "Maranhão", "Pará", "Paraíba", "Paraná",
  "Piauí", "Rondônia",
];

const dictionaries = { en: {}, fr: {}, es: {} };
for (const [source, en, fr, es] of records) {
  dictionaries.en[source] = en;
  dictionaries.fr[source] = fr;
  dictionaries.es[source] = es;
  const normalized = source.replace(/\s+/g, " ").trim();
  dictionaries.en[normalized] = en;
  dictionaries.fr[normalized] = fr;
  dictionaries.es[normalized] = es;
}
for (const name of invariantNames) {
  dictionaries.en[name] = name;
  dictionaries.fr[name] = name;
  dictionaries.es[name] = name;
}

export default dictionaries;
